package com.sdrtouch.tools;
import android.app.PendingIntent;import android.content.*;import android.hardware.usb.*;import android.net.Uri;import android.os.Build;
import com.sdrtouch.testing.FakeContext;import org.junit.*;import java.util.concurrent.*;import static org.junit.Assert.*;
public class UsbPermissionObtainerOfflineTest {
 @After public void sdk(){Build.VERSION.SDK_INT=34;}
 private static void cancelled(Future<?> f)throws Exception{assertTrue(f.isCancelled());try{f.get();fail();}catch(CancellationException expected){}}
 private static void await(CountDownLatch l){try{if(!l.await(1,TimeUnit.SECONDS))throw new AssertionError("latch timeout");}catch(InterruptedException e){throw new AssertionError(e);}}
 @Test(timeout=2000) public void cancelUnregistersBothReceiversAndPendingIntent()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);assertEquals(2,c.registrations.size());assertTrue(f.cancel(true));cancelled(f);assertEquals(0,c.registrations.size());assertEquals(2,c.unregisterCalls);assertEquals(1,c.manager.pending.cancels.get());assertFalse(f.cancel(true));}
 @Test(timeout=2000) public void immutableScopedCallbackDoesNotNeedFillInGrantExtra()throws Exception{FakeContext c=new FakeContext();Future<UsbDeviceConnection> f=UsbPermissionObtainer.obtainFdFor(c,c.device);assertEquals(PendingIntent.FLAG_IMMUTABLE,c.manager.pending.flags);assertEquals(c.getPackageName(),c.manager.pending.intent.getPackage());for(FakeContext.Registration r:c.registrations)assertEquals(Context.RECEIVER_NOT_EXPORTED,r.flags);c.manager.permission=true;c.deliver();assertSame(c.manager.connection,f.get());assertEquals(0,c.registrations.size());assertEquals(1,c.manager.opens.get());c.manager.connection.close();}
 @Test(timeout=2000) public void denialCompletesNullAndCleansUp()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);c.deliver();assertNull(f.get());assertEquals(0,c.manager.opens.get());assertEquals(0,c.registrations.size());}
 @Test(timeout=2000) public void completionCanHappenInsideRequestPermissionBeforeGet()throws Exception{FakeContext c=new FakeContext();c.manager.requestHook=p->{c.manager.permission=true;c.deliver();};Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);assertTrue(f.isDone());assertSame(c.manager.connection,f.get(0,TimeUnit.MILLISECONDS));assertEquals(0,c.registrations.size());c.manager.connection.close();}
 @Test(timeout=2000) public void queuedCallbackAfterCancelDoesNotOpen()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);PendingIntent pi=c.manager.pending;BroadcastReceiver r=c.permissionReceiver;f.cancel(false);c.manager.permission=true;c.deliverQueued(pi,r);assertEquals(0,c.manager.opens.get());cancelled(f);assertEquals(1,pi.cancels.get());}
 @Test(timeout=3000) public void cancelDuringFrameworkOpenClosesRejectedConnection()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);CountDownLatch inside=new CountDownLatch(1),release=new CountDownLatch(1);c.manager.openHook=()->{inside.countDown();await(release);};c.manager.permission=true;Thread t=new Thread(c::deliver);t.setDaemon(true);t.start();await(inside);f.cancel(true);release.countDown();t.join(1000);assertFalse(t.isAlive());assertEquals(1,c.manager.connection.closes.get());assertEquals(0,c.registrations.size());cancelled(f);}
 @Test(timeout=2000) public void uniqueTokensSeparateConcurrentRequests()throws Exception{FakeContext c=new FakeContext();Future<?> a=UsbPermissionObtainer.obtainFdFor(c,c.device);PendingIntent first=c.manager.pending;Future<?> b=UsbPermissionObtainer.obtainFdFor(c,c.device);PendingIntent second=c.manager.pending;assertNotEquals(first.intent.getData(),second.intent.getData());c.manager.permission=true;c.fire(new Intent(first.intent));assertTrue(a.isDone());assertFalse(b.isDone());b.cancel(false);assertEquals(0,c.registrations.size());c.manager.connection.close();}
 @Test(timeout=2000) public void staleTokenDoesNotFinishActiveRequest()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);Intent wrong=new Intent(c.manager.pending.intent).setData(Uri.parse("rtlsdr-permission:other"));c.permissionReceiver.onReceive(c,wrong);assertFalse(f.isDone());f.cancel(false);}
 @Test(timeout=2000) public void missingDeviceIsIgnoredRatherThanCrashing()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);Intent i=new Intent(c.manager.pending.intent.getAction()).setData(c.manager.pending.intent.getData());c.permissionReceiver.onReceive(c,i);assertFalse(f.isDone());f.cancel(false);}
 @Test(timeout=2000) public void wrongDeviceDoesNotFinishActiveRequest()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);Intent i=new Intent(c.manager.pending.intent).putExtra(UsbManager.EXTRA_DEVICE,new UsbDevice("other",20,1,2));c.permissionReceiver.onReceive(c,i);assertFalse(f.isDone());assertEquals(0,c.manager.opens.get());f.cancel(false);}
 @Test(timeout=2000) public void detachCancelsPendingRequest()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);c.fire(new Intent(UsbManager.ACTION_USB_DEVICE_DETACHED).putExtra(UsbManager.EXTRA_DEVICE,c.device));cancelled(f);assertEquals(0,c.registrations.size());}
 @Test(timeout=2000) public void foreignDetachDoesNotCancelSelectedDevice()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);c.fire(new Intent(UsbManager.ACTION_USB_DEVICE_DETACHED).putExtra(UsbManager.EXTRA_DEVICE,new UsbDevice("other",20,1,2)));assertFalse(f.isDone());f.cancel(false);}
 @Test(timeout=2000) public void missingDeviceBeforeRequestDoesNotAskPermission()throws Exception{FakeContext c=new FakeContext();c.manager.devices.clear();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);cancelled(f);assertEquals(0,c.manager.requests.get());assertEquals(0,c.registrations.size());}
 @Test(timeout=2000) public void replacedAttachmentIsNotOpenedOnLateGrant()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);c.manager.devices.put(c.device.getDeviceName(),new UsbDevice(c.device.getDeviceName(),999,0x0bda,0x2838));c.manager.permission=true;c.deliver();assertNull(f.get());assertEquals(0,c.manager.opens.get());assertEquals(0,c.registrations.size());}
 @Test(timeout=2000) public void frameworkRequestFailureCompletesExceptionAndCleansUp()throws Exception{FakeContext c=new FakeContext();c.manager.requestError=new SecurityException("request");Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);try{f.get();fail();}catch(ExecutionException e){assertSame(c.manager.requestError,e.getCause());}assertEquals(0,c.registrations.size());assertEquals(1,c.manager.pending.cancels.get());}
 @Test(timeout=2000) public void partialRegistrationFailureRemovesEarlierReceiver()throws Exception{FakeContext c=new FakeContext();c.failRegisterAt=2;Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);try{f.get();fail();}catch(ExecutionException expected){}assertEquals(0,c.registrations.size());assertEquals(1,c.unregisterCalls);assertEquals(0,c.manager.requests.get());}
 @Test(timeout=2000) public void frameworkOpenFailureStillReleasesRegistrations()throws Exception{FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);c.manager.permission=true;c.manager.openError=new SecurityException("open");c.deliver();try{f.get();fail();}catch(ExecutionException expected){}assertEquals(0,c.registrations.size());}
 @Test(timeout=2000) public void existingGrantTransfersOneConnectionWithoutReceiver()throws Exception{FakeContext c=new FakeContext();c.manager.permission=true;Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);assertTrue(f.isDone());assertFalse(f.cancel(true));assertSame(c.manager.connection,f.get());assertEquals(0,c.registerCalls);assertEquals(0,c.manager.requests.get());c.manager.connection.close();}
 @Test(timeout=2000) public void legacySdkUsesImmutableTokenAndLegacyRegistration()throws Exception{Build.VERSION.SDK_INT=24;FakeContext c=new FakeContext();Future<?> f=UsbPermissionObtainer.obtainFdFor(c,c.device);assertEquals(PendingIntent.FLAG_IMMUTABLE,c.manager.pending.flags);for(FakeContext.Registration r:c.registrations)assertEquals(0,r.flags);f.cancel(false);assertEquals(0,c.registrations.size());}
}
